<style>
[x-cloak]{display:none!important}
.mobile-organization{padding-block:1rem;min-width:0}.mobile-organization h1{font-size:1.6rem}.mobile-organization h2{font-size:1.15rem}.mobile-organization h3{font-size:1rem;font-weight:700;margin:.7rem 0}
.mobile-operation-menu{margin:1rem 0;border:1px solid var(--line);border-radius:.6rem;padding:.75rem}.mobile-operation-menu summary{min-height:2.75rem;display:flex;align-items:center}
.mobile-operation-actions{display:flex;flex-wrap:wrap;align-items:center;gap:.6rem;margin:.75rem 0}.mobile-operation-actions>.fi-btn{flex:1 1 10rem;min-height:2.75rem}
.mobile-phase-picker{display:flex;align-items:end;gap:.5rem;margin:1rem 0}.mobile-phase-picker label{flex:1}.mobile-link-status{color:#7ce4b3}
.mobile-zone{border-top:1px solid var(--line);padding:1rem 0}.mobile-zone-scroll,.mobile-table-scroll,.mobile-competition .fq-bracket-scroll{overflow:auto;max-width:100%;padding-bottom:.75rem;overscroll-behavior-x:contain}
.mobile-zone-rounds{display:flex;gap:1rem;min-width:max-content}.mobile-zone-rounds>section{width:18rem;display:flex;flex-direction:column;justify-content:space-around;gap:1rem}
.mobile-match,.mobile-competition .fq-match{background:var(--surface);padding:.75rem;border:1px solid var(--line);border-left:3px solid #418bff;border-radius:.6rem;min-width:0}
.mobile-match-label{font-size:.8rem;color:var(--muted)}.mobile-competition .fq-match-player{display:flex;align-items:center;justify-content:space-between;gap:.5rem;font-size:.85rem;min-height:2.5rem}.mobile-competition .fq-match-player>span:first-child{min-width:0;overflow-wrap:anywhere}
.mobile-competition .is-winner{color:#7ce4b3;font-weight:700}.mobile-match-actions,.mobile-competition .fq-match-actions{display:flex;align-items:center;flex-wrap:wrap;justify-content:flex-end;gap:.45rem;margin-top:.5rem;position:static;opacity:1;visibility:visible}
.mobile-competition .fi-icon-btn{min-width:2.75rem;min-height:2.75rem}.mobile-match p{font-size:.75rem}
.mobile-standings{border-collapse:collapse;min-width:100%;font-size:.8rem}.mobile-standings th,.mobile-standings td{padding:.5rem;text-align:left;white-space:nowrap;border-bottom:1px solid var(--line)}
.mobile-competition .fq-bracket{display:grid;gap:1.5rem;min-width:max-content!important}.mobile-competition .fq-round{width:19rem;display:flex;flex-direction:column;justify-content:space-around;gap:1rem}.mobile-competition .fq-match-shell{position:relative}.mobile-competition .fq-round:not(:last-child) .fq-match-shell:after{content:'';position:absolute;width:1.5rem;right:-1.5rem;top:50%;border-top:1px solid var(--line)}
.mobile-competition .fq-match-time,.mobile-competition .fq-table-active{font-size:.75rem;color:var(--muted)}.mobile-competition .fq-match.is-called{border-color:#c8a137}.mobile-competition .fq-match.is-in-progress{border-color:#32b280}.mobile-competition .fq-place{border:1px solid #418bff;border-radius:.5rem;padding:.5rem;margin:.5rem 0;display:grid;gap:.3rem;text-align:center}
.mobile-competition .fq-set-point{display:inline-flex;padding:.25rem;border:1px solid var(--line)}.mobile-competition .fq-set-scores{display:flex;gap:.2rem}.mobile-competition .finalist-card{display:none}
.mobile-organization-shell .fi-modal{color:#f0f5fd}.mobile-organization-shell .fi-modal-window{max-width:calc(100vw - 1rem);max-height:calc(100dvh - 1rem)}
.mobile-competition .fq-qualified-dialog{width:calc(100vw - 1.5rem);max-width:45rem;max-height:85dvh;background:var(--bg);color:var(--ink);padding:1rem;border:1px solid var(--line);border-radius:.6rem}.mobile-competition .fq-qualified-dialog::backdrop{background:#0009}.mobile-competition .fq-qualified-dialog-head,.mobile-competition .fq-qualified-dialog-actions{display:flex;justify-content:space-between;align-items:center;gap:.4rem}.mobile-competition .fq-qualified-dialog-actions svg{width:1.2rem;height:1.2rem}.mobile-competition .fq-standings-wrap{overflow:auto;max-height:60dvh}.mobile-competition .fq-standings th,.mobile-competition .fq-standings td{font-size:.8rem;padding:.5rem;white-space:nowrap;border-bottom:1px solid var(--line)}
